namespace DogSC.Replica {
 static class DialogTestDriver {
  public static void WithCard(Action open,Action<AppDialogWindow> answer){Exception failure=null;bool answered=false;var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(90)};timer.Tick+=(s,e)=>{var card=Application.Current.Windows.OfType<AppDialogWindow>().FirstOrDefault(w=>w.IsLoaded);if(card==null)return;timer.Stop();answered=true;try{answer(card);}catch(Exception ex){failure=ex;card.Close();}};timer.Start();try{open();}finally{timer.Stop();}if(failure!=null)throw failure;if(!answered)throw new Exception("Expected product dialog did not appear");}
  public static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
  public static void Escape(UIElement target){target.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(target),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});}
  public static ColorPalette FindPalette(){foreach(HwndSource source in PresentationSource.CurrentSources.OfType<HwndSource>()){var found=Find<ColorPalette>(source.RootVisual);if(found!=null)return found;}return null;}
  static T Find<T>(DependencyObject node) where T:DependencyObject {if(node==null)return null;if(node is T)return (T)node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++){var result=Find<T>(VisualTreeHelper.GetChild(node,i));if(result!=null)return result;}return null;}
 }
