 public partial class ExportWindow {
  public async Task VerifyExportInteractions(string folder,Studio studio){
   outputFolder=folder;fileName.Text="bad:name";DialogTestDriver.WithCard(BeginExport,card=>DialogTestDriver.Click(card.Actions["ok"]));if(cancellation!=null)throw new Exception("Invalid filename began export");
   string sentinel=Path.Combine(folder,"existing.mp4");File.WriteAllText(sentinel,"keep existing video");fileName.Text="existing";DialogTestDriver.WithCard(BeginExport,card=>DialogTestDriver.Escape(card));if(File.ReadAllText(sentinel)!="keep existing video")throw new Exception("Existing file overwritten");
   fileName.Text="cancelled";BeginExport();CancelOrOpen();var watch=System.Diagnostics.Stopwatch.StartNew();while(cancellation!=null&&watch.Elapsed.TotalSeconds<20)await Task.Delay(60);if(cancellation!=null||done||!panel.IsEnabled||!start.IsEnabled||!cancel.IsEnabled||File.Exists(Path.Combine(folder,"cancelled.mp4"))||Directory.GetDirectories(folder,".dogsc-*").Length!=0)throw new Exception("Cancel failed to restore UI or clean partial export");
   outputHeight=360;outputFps=6;fileName.Text="finished";BeginExport();watch.Restart();while(cancellation!=null&&watch.Elapsed.TotalSeconds<45)await Task.Delay(60);if(cancellation!=null||!done||!File.Exists(completedOutput)||!IsVisible||(string)cancel.Content!="打开文件夹")throw new Exception("Export retry/completion actions failed");UI.SaveImage((FrameworkElement)Content,Path.Combine(folder,"export-complete.png"));Close();
   var closing=new ExportWindow(studio,doc,null);closing.outputFolder=folder;closing.fileName.Text="closed";closing.Show();closing.BeginExport();closing.Close();watch.Restart();while(closing.cancellation!=null&&watch.Elapsed.TotalSeconds<20)await Task.Delay(60);if(closing.cancellation!=null||closing.IsVisible||File.Exists(Path.Combine(folder,"closed.mp4")))throw new Exception("Closing active export did not cancel and dismiss");
  }
